392	                GraphError::Manifest(callisto_model::ManifestError::MissingField {
393	                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
394	                    field: "version",
395	                })
396	            })?;
397	
398	        let native_names: Vec<_> = identity.native_names(&pkg.id).collect();
399	        let policy = resolve_package_config(&native_names, config)
400	            .and_then(|pcfg| pcfg.pre_major_inference)
401	            .unwrap_or(PreMajorInferencePolicy::Off);
402	
403	        // release_trigger: Changeset packages take severity from pending changesets only --
404	        // commit inference must not run for them, so neither does resolving its window.
405	        let inferred = if pkg.release_trigger == ReleaseTrigger::Auto {
406	            let since = last_tag
407	                .map(|t| resolve_since(git, tags, t.name.as_str()))
408	                .transpose()?;
