410	                pathspecs: &pathspecs,
411	                since,
412	                current_version: &cur_ver,
413	                has_prior_release: last_tag.is_some(),
414	                policy,
415	            };
416	            inference.infer(pkg, git, window)?
417	        } else {
418	            None
419	        };
