421	        if let Some(outcome) = inferred
422	            && outcome.severity > Severity::None
423	        {
424	            agg.add(
425	                &pkg.id,
426	                outcome.severity,
427	                Source::Inference {
428	                    commits: outcome.commit_count,
429	                    remapped: outcome.remapped,
