440	        .unwrap_or(false);
441	    // Ids already recorded in pre.json still resolve for severity, but are not re-added to the changelog.
442	    let already_recorded: std::collections::HashSet<&str> = pre
443	        .and_then(|s| s.changesets())
444	        .map(|ids| ids.iter().map(String::as_str).collect())
445	        .unwrap_or_default();
