147	) -> Result<ApplyOutcome, GraphError> {
148	    let mut outcome = ApplyOutcome::default();
149	    let mut modified_paths = Vec::new();
150	    let mut deferred_deletions = Vec::new();
151	
152	    let ctx = OpenContext::for_workspace_root(root)?;
153	    preflight::check(root, plan, opts, permit, runner)?;
154	    let active_ecosystems = active_ecosystems(plan);
155	    // Resolved before the first write, so a workspace that cannot be found stops the run with nothing changed.
156	    let cargo_workspaces = if active_ecosystems.contains(&Ecosystem::Cargo) {
157	        touched_cargo_workspaces(root, plan)?
158	    } else {
159	        BTreeSet::new()
160	    };
161	    let lockfile_dirs = lockfile_dirs(root, plan, &active_ecosystems)?;
