164	    for step in write_steps(plan, &classification) {
165	        modified_paths.push(apply_write_step(&step, plan, root, &ctx, permit)?);
166	    }
167	
168	    if !opts.transient {
169	        for cl in &plan.changelog_writes {
170	            let rendered = crate::changelog::render_section(&cl.input)?;
171	            crate::changelog::prepend(
172	                root,
173	                &cl.changelog_path,
174	                &cl.input.package.display_name(),
175	                &rendered,
176	                permit,
177	            )?;
178	            modified_paths.push(cl.changelog_path.clone());
179	        }
180	
181	        for cs_path in &plan.consumed_changesets {
182	            deferred_deletions.push(cs_path.clone());
183	        }
184	        for archived in &plan.archived_changesets {
185	            let from = root.join(&archived.from);
186	            let text = fs::read_to_string(&from).map_err(|e| GraphError::ApplyIo {
187	                path: archived.from.clone(),
188	                message: e.to_string(),
189	            })?;
190	            callisto_model::atomic::atomic_write(&root.join(&archived.to), &text, permit).map_err(|e| {
191	                GraphError::ApplyIo {
192	                    path: archived.to.clone(),
193	                    message: e.to_string(),
194	                }
195	            })?;
196	            modified_paths.push(archived.to.clone());
197	            deferred_deletions.push(archived.from.clone());
198	        }
199	
200	        if let Some(ref pre_state) = plan.pre_state_update {
201	            // Written from `plan.pre_json_path`, not derived from `consumed_changesets` (always empty in pre mode).
202	            let rel_pre_path = plan.pre_json_path.clone();
203	            let pre_path = root.join(&rel_pre_path);
204	            let text = match &plan.pre_json_original_text {
205	                Some(existing) => callisto_model::format::write_pre_json_preserving(pre_state, existing),
206	                None => callisto_model::format::write_pre_json(pre_state),
207	            };
208	            callisto_model::atomic::atomic_write(&pre_path, &text, permit).map_err(|e| GraphError::ApplyIo {
209	                path: rel_pre_path.clone(),
210	                message: e.to_string(),
211	            })?;
212	            modified_paths.push(rel_pre_path);
213	        } else if let Some(rel_pre_path) = &plan.delete_pre_json {
214	            deferred_deletions.push(rel_pre_path.clone());
215	        }
216	    }
217	
218	    // Must run before the staging loop below, so refreshed lockfiles are on disk to be staged.
219	    if opts.refresh_lockfiles {
220	        let refresh_results = refresh_lockfiles(runner, root, &cargo_workspaces, &lockfile_dirs)?;
221	        if !refresh_results.is_empty() {
222	            outcome.lockfile_refresh_results = Some(refresh_results);
223	        }
224	    }
225	
226	    // Stage each lockfile of an active ecosystem that exists beside the workspace the plan wrote into.
227	    let mut lockfile_paths: Vec<PathBuf> = Vec::new();
228	    for p in lockfile_candidate_paths(&lockfile_dirs, &cargo_workspaces) {
229	        if path_exists(root, &p)? && !modified_paths.contains(&p) {
