251	            } else {
252	                deleted.push(path);
253	            }
254	        }
255	
256	        if !existing.is_empty() {
257	            run_git_on_paths(runner, root, &["add", "--"], &existing)?;
258	        }
259	
260	        if !deleted.is_empty() {
261	            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deleted)?;
262	        }
263	
264	        if !deferred_deletions.is_empty() {
265	            let deferred: Vec<&PathBuf> = deferred_deletions.iter().collect();
266	            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deferred)?;
267	
268	            // Keep the inputs on disk until their removal is staged so a failed index update can be retried.
269	            for path in &deferred_deletions {
270	                match fs::remove_file(root.join(path)) {
