/// Writes `plan` to disk and stages the touched paths in git.
///
/// Every side effect here is unconditional -- whether to apply at all is
/// the caller's decision, which is why an [`ApplyPermit`] is required
/// rather than a `dry_run` bool: a bool carries no guarantee any caller
/// actually consulted it. A dry-run caller can't obtain a permit and
/// simply doesn't call this function; it reports `plan` instead.
///
/// # Errors
///
/// - A target the plan would write that cannot be written (missing, a directory, behind a symbolic link, unreadable
///   or in a directory that takes no new file); this is checked for every target before the first write.
/// - Manifest parse/write failures (malformed TOML/JSON, unsupported format).
/// - Git subprocess failures (`git add`/`git rm --cached` non-zero exit).
/// - I/O errors writing changelog sections or `pre.json`.
pub fn apply_version_plan<R: CommandRunner>(
    root: &Path,
    plan: &VersionPlan,
    runner: &R,
    opts: &ApplyOptions,
    permit: &ApplyPermit,
) -> Result<ApplyOutcome, GraphError> {
    let mut outcome = ApplyOutcome::default();
    let mut modified_paths = Vec::new();
    let mut deferred_deletions = Vec::new();

    let ctx = OpenContext::for_workspace_root(root)?;
    preflight::check(root, plan, opts, permit, runner)?;
    let active_ecosystems = active_ecosystems(plan);
    // Resolved before the first write, so a workspace that cannot be found stops the run with nothing changed.
    let cargo_workspaces = if active_ecosystems.contains(&Ecosystem::Cargo) {
        touched_cargo_workspaces(root, plan)?
    } else {
        BTreeSet::new()
    };
    let lockfile_dirs = lockfile_dirs(root, plan, &active_ecosystems)?;
    let classification = classify_manifest_writes(plan);

    for step in write_steps(plan, &classification) {
        modified_paths.push(apply_write_step(&step, plan, root, &ctx, permit)?);
    }

    if !opts.transient {
        for cl in &plan.changelog_writes {
            let rendered = crate::changelog::render_section(&cl.input)?;
            crate::changelog::prepend(
                root,
                &cl.changelog_path,
                &cl.input.package.display_name(),
                &rendered,
                permit,
            )?;
            modified_paths.push(cl.changelog_path.clone());
        }

        for cs_path in &plan.consumed_changesets {
            deferred_deletions.push(cs_path.clone());
        }
        for archived in &plan.archived_changesets {
            let from = root.join(&archived.from);
            let text = fs::read_to_string(&from).map_err(|e| GraphError::ApplyIo {
                path: archived.from.clone(),
                message: e.to_string(),
            })?;
            callisto_model::atomic::atomic_write(&root.join(&archived.to), &text, permit).map_err(|e| {
                GraphError::ApplyIo {
                    path: archived.to.clone(),
                    message: e.to_string(),
                }
            })?;
            modified_paths.push(archived.to.clone());
            deferred_deletions.push(archived.from.clone());
        }

        if let Some(ref pre_state) = plan.pre_state_update {
            // Written from `plan.pre_json_path`, not derived from `consumed_changesets` (always empty in pre mode).
            let rel_pre_path = plan.pre_json_path.clone();
            let pre_path = root.join(&rel_pre_path);
            let text = match &plan.pre_json_original_text {
                Some(existing) => callisto_model::format::write_pre_json_preserving(pre_state, existing),
                None => callisto_model::format::write_pre_json(pre_state),
            };
            callisto_model::atomic::atomic_write(&pre_path, &text, permit).map_err(|e| GraphError::ApplyIo {
                path: rel_pre_path.clone(),
                message: e.to_string(),
            })?;
            modified_paths.push(rel_pre_path);
        } else if let Some(rel_pre_path) = &plan.delete_pre_json {
            deferred_deletions.push(rel_pre_path.clone());
        }
    }

    // Must run before the staging loop below, so refreshed lockfiles are on disk to be staged.
    if opts.refresh_lockfiles {
        let refresh_results = refresh_lockfiles(runner, root, &cargo_workspaces, &lockfile_dirs)?;
        if !refresh_results.is_empty() {
            outcome.lockfile_refresh_results = Some(refresh_results);
        }
    }

    // Stage each lockfile of an active ecosystem that exists beside the workspace the plan wrote into.
    let mut lockfile_paths: Vec<PathBuf> = Vec::new();
    for p in lockfile_candidate_paths(&lockfile_dirs, &cargo_workspaces) {
        if path_exists(root, &p)? && !modified_paths.contains(&p) {
            lockfile_paths.push(p.clone());
            modified_paths.push(p);
        }
    }

    // A lockfile that a .gitignore ignores (a library's `Cargo.lock`, say) is not meant to be committed: refreshed on disk,
    // never staged. Anything else the plan stages was checked before the first write.
    if !opts.transient {
        let ignored = preflight::ignored_paths(runner, root, &lockfile_paths)?;
        modified_paths.retain(|path| !ignored.contains(path));
    }

    if !opts.transient && (!modified_paths.is_empty() || !deferred_deletions.is_empty()) {
        // Stage all written release state before consuming its inputs. If a refresh or add fails,
        // the changesets/pre-state remain available; if removal staging fails, the manifest diff
        // still identifies the interrupted run.
        let mut existing = Vec::new();
        let mut deleted = Vec::new();
        for path in &modified_paths {
            if path_exists(root, path)? {
                existing.push(path);
            } else {
                deleted.push(path);
            }
        }

        if !existing.is_empty() {
            run_git_on_paths(runner, root, &["add", "--"], &existing)?;
        }

        if !deleted.is_empty() {
            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deleted)?;
        }

        if !deferred_deletions.is_empty() {
            let deferred: Vec<&PathBuf> = deferred_deletions.iter().collect();
            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deferred)?;

            // Keep the inputs on disk until their removal is staged so a failed index update can be retried.
            for path in &deferred_deletions {
                match fs::remove_file(root.join(path)) {
                    Ok(()) => {}
                    Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
                    Err(e) => {
                        return Err(GraphError::ApplyIo {
                            path: path.clone(),
                            message: e.to_string(),
                        })
                    }
                }
            }
            modified_paths.extend(deferred_deletions.iter().cloned());
        }

        outcome.staged = modified_paths;
    }

    Ok(outcome)
}

/// Everything `apply_version_plan` checks before its first write: that each target can be written and staged, and that
/// the Cargo workspaces and lockfile directories it will refresh resolve. A caller that must not leave state behind
/// when the apply cannot start (a checkpoint) runs this first.
pub fn validate_plan<R: CommandRunner>(
    root: &Path,
    plan: &VersionPlan,
    opts: &ApplyOptions,
    permit: &ApplyPermit,
    runner: &R,
) -> Result<(), GraphError> {
    preflight::check(root, plan, opts, permit, runner)?;
    let active = active_ecosystems(plan);
    if active.contains(&Ecosystem::Cargo) {
        touched_cargo_workspaces(root, plan)?;
    }
    lockfile_dirs(root, plan, &active)?;
    Ok(())
}

fn lockfile_candidate_paths(dirs: &LockfileDirs, cargo_workspaces: &BTreeSet<PathBuf>) -> Vec<PathBuf> {
    let beside = |dirs: &BTreeSet<PathBuf>, names: &[&str]| -> Vec<PathBuf> {
        dirs.iter()
            .flat_map(|dir| names.iter().map(move |name| dir.join(name)))
            .collect()
    };
    beside(&dirs.npm, &NPM_LOCKFILES)
        .into_iter()
        .chain(beside(&dirs.pypi, &PYPI_LOCKFILES))
        .chain(cargo_workspaces.iter().map(|workspace| cargo_lockfile(workspace)))
        .collect()

