/// Every path `plan` writes, creates or deletes (manifests, changelogs, consumed changesets, `pre.json`). Lockfiles
/// are not included: tools refresh them.
pub fn written_paths(plan: &VersionPlan) -> BTreeSet<PathBuf> {
    preflight::written_paths(plan)
}

/// One physical write of a version plan, in the order it must happen.
enum WriteStep<'p> {
    /// One load/mutate/persist cycle over a manifest only the `Manifest` trait writes: the
    /// version bump (idempotency-guarded) first, then every dependency rewrite, one persist.
    Manifest {
        path: &'p PathBuf,
        group: &'p ManifestWriteGroup,
    },
    /// The same cycle for a Cargo workspace root only the `WorkspaceCargoResolver` writes. Its
    /// writes carry no idempotency precondition.
    WorkspaceRoot {
        root_manifest: &'p PathBuf,
        group: &'p ManifestWriteGroup,
    },
    /// Mixed-routing manifests (written through both routes) are never batched: each write is
    /// its own load/persist, strictly in plan order.
    MixedManifestVersion {
        path: &'p PathBuf,
            DepWriteTarget::CargoWorkspaceDependency { root_manifest } => root_manifest,
        };
        targets.insert((path.clone(), Target::Existing));
    }
    targets.extend(
        plan.platform_writes
            .iter()
            .map(|write| (write.manifest.clone(), Target::Existing)),
    );
    targets.extend(
        plan.optional_dep_updates
            .iter()
            .map(|update| (update.manifest.clone(), Target::Existing)),
    );
    if !opts.transient {
        targets.extend(
            plan.changelog_writes
                .iter()
                .map(|write| (write.changelog_path.clone(), Target::Creatable)),
        );
        targets.extend(
            plan.consumed_changesets
                .iter()
                .map(|path| (path.clone(), Target::Removed)),
        );
        for archived in &plan.archived_changesets {
            targets.insert((archived.from.clone(), Target::Removed));
            targets.insert((archived.to.clone(), Target::Creatable));
        }
        if plan.pre_state_update.is_some() {
            targets.insert((plan.pre_json_path.clone(), Target::Creatable));
        } else if let Some(path) = &plan.delete_pre_json {
            targets.insert((path.clone(), Target::Removed));
        }
    }
    targets
}

