470	/// The commit has the shape of a version commit: it wrote the decision and touched only the paths a version commit may
471	/// touch.
472	fn require_version_commit_shape<R: CommandRunner, D: DependencyResolver>(
473	    workspace: &Workspace<'_, R, D>,
474	    release_commit: &CommitSha,
475	    changed: &[(String, String)],
476	    decision_path: &str,
477	) -> Result<(), GraphError> {
478	    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
479	
480	    // The decision must be written by this commit, not left over from an earlier release.
481	    let decision_freshly_written = changed
482	        .iter()
483	        .any(|(status, path)| path == decision_path && matches!(status.as_str(), "A" | "M"));
484	    if !decision_freshly_written {
485	        return Err(GraphError::ReleaseCommitVerificationFailed {
486	            commit: release_commit.clone(),
487	            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
488	        });
489	    }
490	
491	    // A version commit changes versions and what records them, nothing else. Any other path (build scripts, source,
492	    // a package manager's `.npmrc` or `.cargo/config.toml`, `callisto.toml`, an action) could change what is published
493	    // or where, under the cover of a bot-authored diff.
494	    let changelogs = workspace
495	        .graph
496	        .packages()
497	        .filter_map(|package| package.changelog.as_deref())
498	        .map(normalized_git_path)
499	        .collect::<Result<std::collections::BTreeSet<_>, _>>()?;
500	    for (_, path) in changed {
501	        if !is_version_commit_path(path, decision_path, &changeset_dir, &changelogs) {
502	            return Err(GraphError::ReleaseCommitVerificationFailed {
503	                commit: release_commit.clone(),
504	                reason: CommitVerificationFailure::UnexpectedPath { path: path.clone() },
505	            });
506	        }
507	    }
508	    Ok(())
509	}
