511	/// The commit deletes exactly the changesets the decision recorded. A decision from before that record must delete at
512	/// least one, since every release then started from a changeset.
513	fn require_recorded_changesets_consumed<R: CommandRunner, D: DependencyResolver>(
514	    workspace: &Workspace<'_, R, D>,
515	    release_commit: &CommitSha,
516	    changed: &[(String, String)],
517	    decision: &ReleaseDecisionV1,
518	) -> Result<(), GraphError> {
519	    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
520	    let deleted: std::collections::BTreeSet<&str> = changed
521	        .iter()
522	        .filter(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir))
523	        .map(|(_, path)| path.as_str())
524	        .collect();
525	    let consumed_as_recorded = match &decision.consumed_changesets {
526	        Some(recorded) => recorded.iter().map(String::as_str).eq(deleted.iter().copied()),
527	        None => !deleted.is_empty(),
528	    };
529	    if !consumed_as_recorded {
530	        return Err(GraphError::ReleaseCommitVerificationFailed {
531	            commit: release_commit.clone(),
532	            reason: CommitVerificationFailure::ConsumedChangesetsDiffer,
533	        });
534	    }
535	    Ok(())
536	}
