539	fn read_committed_decision<R: CommandRunner, D: DependencyResolver>(
540	    workspace: &Workspace<'_, R, D>,
541	    release_commit: &CommitSha,
542	    decision_path: &std::path::Path,
543	    decision_path_str: &str,
544	) -> Result<ReleaseDecisionV1, GraphError> {
545	    let decision_source = git_file(
546	        workspace.runner,
547	        &workspace.root,
548	        release_commit.as_str(),
549	        decision_path_str,
550	    )?;
551	    serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
552	        path: decision_path.to_path_buf(),
553	        message: error.to_string(),
554	    })
555	}
