557	/// Every package the decision claims has its changelog and manifest in the diff with exactly the claimed version, and
558	/// no package the decision does not claim changed version.
559	fn require_manifests_match_decision<R: CommandRunner, D: DependencyResolver>(
560	    workspace: &Workspace<'_, R, D>,
561	    release_commit: &CommitSha,
562	    parent: &str,
563	    changed: &[(String, String)],
564	    decision: &ReleaseDecisionV1,
565	) -> Result<(), GraphError> {
566	    let claimed = decision
567	        .entries
568	        .iter()
569	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
570	        .collect::<std::collections::BTreeMap<_, _>>();
571	
572	    let changed_paths = changed
573	        .iter()
574	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
575	        .collect::<std::collections::BTreeSet<_>>();
576	
577	    // Both traversals walk `packages()` and `canonical_manifests()` in the same ordered storage, so batched results zip back by position.
578	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
579	        .graph
580	        .packages()
581	        .flat_map(Package::canonical_manifests)
582	        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
583	        .collect::<Result<_, GraphError>>()?;
584	    // Each Cargo manifest may inherit its version from a workspace manifest above it, so those are fetched too.
585	    let mut query_path_list: Vec<String> = manifest_queries.iter().map(|(path, _)| path.clone()).collect();
586	    for (path, _) in manifest_queries
587	        .iter()
588	        .filter(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
589	    {
590	        for candidate in callisto_manifests::workspace_manifest_candidates(&workspace.root, std::path::Path::new(path))?
591	        {
592	            let candidate = normalized_git_path(&candidate)?;
593	            if !query_path_list.contains(&candidate) {
594	                query_path_list.push(candidate);
595	            }
596	        }
597	    }
598	    let query_paths: Vec<&str> = query_path_list.iter().map(String::as_str).collect();
599	
600	    // Exactly two `git cat-file --batch` invocations in all (one per commit), however many canonical manifests the
601	    // workspace has.
602	    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, parent, &query_paths)?;
603	    let after_blobs =
604	        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
605	    let before = CommitBlobs::new(workspace.runner, &workspace.root, parent, &query_paths, before_blobs);
606	    let after = CommitBlobs::new(
607	        workspace.runner,
608	        &workspace.root,
609	        release_commit.as_str(),
610	        &query_paths,
611	        after_blobs,
612	    );
613	    let before_versions = resolve_batch_versions(&before, &manifest_queries)?;
614	    let after_versions = resolve_batch_versions(&after, &manifest_queries)?;
615	
616	    let mut observed = std::collections::BTreeSet::new();
617	    let mut manifest_index = 0usize;
618	    for package in workspace.graph.packages() {
619	        let package_ids = release_package_ids(&workspace.identity, package)?;
620	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
621	        if package_is_claimed {
622	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
623	                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
624	            })?;
625	            let changelog = normalized_git_path(changelog)?;
626	            if !changed_paths.contains(changelog.as_str()) {
627	                return Err(GraphError::ReleaseCommitVerificationFailed {
628	                    commit: release_commit.clone(),
629	                    reason: CommitVerificationFailure::ChangelogNotTouched,
630	                });
631	            }
632	        }
633	        for id in package_ids {
634	            let before = &before_versions[manifest_index];
635	            let after = &after_versions[manifest_index];
636	            manifest_index += 1;
637	            let changed_version = before.version != after.version;
638	            match claimed.get(&id) {
639	                Some(target_version) => {
640	                    if !changed_paths.contains(after.authority.to_string_lossy().as_ref()) {
641	                        return Err(GraphError::ReleaseCommitVerificationFailed {
642	                            commit: release_commit.clone(),
643	                            reason: CommitVerificationFailure::ManifestNotInDiff,
644	                        });
645	                    }
646	                    if !changed_version || &after.version != target_version {
647	                        return Err(GraphError::ReleaseCommitVerificationFailed {
648	                            commit: release_commit.clone(),
649	                            reason: CommitVerificationFailure::ManifestVersionMismatch,
650	                        });
651	                    }
652	                    observed.insert(id);
653	                }
654	                None => {
655	                    if changed_version {
656	                        // A changed version the committed decision never
657	                        // claimed is not this commit's authority -- fail
658	                        // closed rather than trust a partial match.
659	                        return Err(GraphError::ReleaseCommitVerificationFailed {
660	                            commit: release_commit.clone(),
661	                            reason: CommitVerificationFailure::UnclaimedVersionChange,
662	                        });
663	                    }
664	                }
665	            }
666	        }
667	    }
668	    if observed.len() != claimed.len() {
669	        return Err(GraphError::ReleaseCommitVerificationFailed {
670	            commit: release_commit.clone(),
671	            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
672	        });
673	    }
674	    Ok(())
675	}
